// QA cycle (Nov 2026): browser test cases. Signs in through "Demo quick access", fills forms, checks menus. Changes nothing in the app.
//   npm run build && node qa/ui.mjs   → qa/results-ui.json
import { chromium } from 'playwright';
import { writeFileSync, readFileSync } from 'fs';
import { serve } from '../tests/store/serve.mjs';
import { DEFAULT_RATE_CARD as RC, blankOptions, demoConfig } from '../src/lib/pricing.js';
import { buildSeed } from '../src/data/seed.js';
import { departmentOf } from '../src/data/designations.js';
const SEED = JSON.stringify(buildSeed());

const server = await serve(new URL('../dist', import.meta.url).pathname);
const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', args: ['--no-sandbox'] });
const KEY = 'school-app-demo-v9';
const cases = []; const menusByRole = {};
const logic = JSON.parse(readFileSync(new URL('./results-logic.json', import.meta.url)));
const plusDays = (k) => { const d = new Date(); d.setDate(d.getDate() + k); return d.toISOString().slice(0, 10); };

async function start() {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 1000 } });
  const page = await ctx.newPage(); page.setDefaultTimeout(5000);
  page.errors = []; page.on('pageerror', (e) => page.errors.push(e.message));
  await page.addInitScript((seed) => { window.__seed = seed; }, SEED);
  await page.goto(server.url + '#/login');
  return page;
}
async function as(page, label) {
  const sw = page.getByRole('button', { name: 'Switch user' });
  if (await sw.count()) await sw.click();
  await page.getByRole('tab', { name: 'Demo quick access' }).click();
  await page.locator('.rolegrid button').filter({ has: page.locator('.b', { hasText: new RegExp('^' + label.replace(/[+&]/g, (c) => '\\' + c) + '$') }) }).first().click();
  await page.locator('nav.side, .topmenu').first().waitFor();
  await page.waitForTimeout(250);
}
const go = async (page, code) => { await page.goto(server.url + '#/s/' + code); await page.waitForTimeout(250); };
const heading = (page) => page.locator('main h1').first().innerText().catch(() => '');
const toast = async (page) => (await page.locator('.toast, [role=status].toast, .notify').allInnerTexts().catch(() => [])).join(' | ');
const modal = (page) => page.locator('.modal').last();
async function tc(meta, fn) {
  const c = { suite: 'UI', tier: 'All', addon: '—', ...meta };
  let page;
  try { page = await start(); const r = await fn(page); c.actual = r.actual; c.status = r.pass ? 'Pass' : 'Fail'; if (page.errors.length) { c.actual += ' · page error: ' + page.errors[0]; c.status = 'Fail'; } }
  catch (e) { c.actual = 'Error: ' + e.message.split('\n')[0]; c.status = 'Fail'; }
  finally { await page?.context().close(); }
  cases.push(c); process.stdout.write(c.status === 'Pass' ? '.' : 'F');
}
// Main menu: every module and sub-menu shown to this person
async function mainMenu(page) {
  await go(page, 'HOME');
  return page.locator('main section.card[aria-label]').evaluateAll((ss) => Object.fromEntries(ss.map((s) => [s.getAttribute('aria-label'), [...s.querySelectorAll('button')].map((b) => b.querySelector('.b')?.innerText || b.innerText.trim())])));
}
async function inject(page, change) {
  await page.evaluate(([k, src, seed]) => { const d = JSON.parse(localStorage.getItem(k) || seed); new Function('d', src)(d); d.rev = (d.rev || 0) + 1; localStorage.setItem(k, JSON.stringify(d)); }, [KEY, change, SEED]);
  await page.reload(); await page.waitForTimeout(400);
}
const save = async (page) => { await page.evaluate(() => 0); };

// ---------------------------------------------------------------- Roles: login, menus, direct links to screens not allowed
const ROLE_UI = [
  ['Admin', ['OPS_USERS', 'DASH'], ['SELF_CHILD', 'PLT_SCHOOLS']], ['Principal', ['STU_LIST', 'ANL_TEACHER'], ['OPS_USERS', 'FEE_COLLECT']], ['Accountant', ['FEE_COLLECT', 'PAY_RUN'], ['EXM_QB', 'OPS_USERS']],
  ['Teacher', ['STU_ATT', 'EXM_QB'], ['FEE_COLLECT', 'OPS_USERS', 'PAY_RUN']], ['Teacher + Vice Principal', ['OPS_USERS', 'ANL_TEACHER'], ['FEE_COLLECT']], ['Teacher + Head of Teaching Staff', ['ANL_TEACHER'], ['OPS_USERS']],
  ['Front Office', ['STU_ADMIT', 'STU_GATE'], ['PAY_RUN', 'EXM_QB']], ['Parent', ['SELF_CHILD', 'SELF_FEES'], ['STU_LIST', 'FEE_COLLECT', 'OPS_USERS']],
  ['Transport team', ['TRN_MANIFEST', 'TRN_ROUTES'], ['STU_LIST', 'FEE_COLLECT']], ['Platform team', ['PLT_SCHOOLS'], ['STU_LIST', 'FEE_COLLECT']], ['Sales & marketing', ['SP_PROPOSAL', 'SP_RATES'], ['STU_LIST', 'PLT_SCHOOLS', 'FEE_COLLECT']]];
for (const [label, allowed, denied] of ROLE_UI) {
  await tc({ id: `UI-ROLE-${label.replace(/\W+/g, '')}-01`, module: 'Login & access', menu: 'Main menu', feature: 'Role menus', role: label, type: 'Positive', category: 'Login / role menus',
    title: `${label}: signs in and sees their menus`, steps: `Demo quick access → ${label}; open Main menu`, expected: `Lands on the app; Main menu lists only allowed menus; can open ${allowed.join(', ')}` },
  async (page) => { await as(page, label); const m = await mainMenu(page); menusByRole[label] = m; const opened = [];
    for (const c of allowed) { await go(page, c); opened.push(`${c}:${(await page.evaluate(() => location.hash)).includes(c) ? 'opens' : 'redirected'}`); }
    return { actual: `${Object.keys(m).length} menus (${Object.keys(m).join(', ')}); ${opened.join(', ')}`, pass: opened.every((x) => x.endsWith('opens')) }; });
  await tc({ id: `UI-ROLE-${label.replace(/\W+/g, '')}-02`, module: 'Login & access', menu: denied.join(', '), feature: 'Unauthorized access', role: label, type: 'Negative', category: 'Unauthorized access',
    title: `${label}: direct links to ${denied.join(', ')} are refused`, steps: `Signed in as ${label}, open #/s/<code> for each`, expected: 'Each opens the Main menu with “… is not available for your account”' },
  async (page) => { await as(page, label); const r = [];
    for (const c of denied) { await go(page, c); await page.waitForTimeout(200); const h = await page.evaluate(() => location.hash); const t = await toast(page); r.push(`${c}:${h.includes(c) ? 'OPENED' : 'blocked'}${/not available/.test(t) ? ' (message)' : ''}`); }
    return { actual: r.join(', '), pass: r.every((x) => x.includes('blocked')) }; });
}
// Read-only department access: Principal set to read-only on Students → buttons disabled
const PDEPT = departmentOf(buildSeed(), 'PRINCIPAL');
await tc({ id: 'UI-ROLE-ReadOnly-01', module: 'Operations', menu: 'Roles & Permissions', feature: 'Read-only access', role: 'Principal', type: 'Negative', category: 'Action not permitted for role',
  title: 'A screen set to read-only for a department cannot be changed', steps: `Set Staff Attendance read-only for ${PDEPT}; sign in as Principal; Staff Attendance → mark A`, expected: '“Read only — you can view … but not change anything”; nothing saved' },
async (page) => { await as(page, 'Admin'); await inject(page, `d.deptReadOnly={...(d.deptReadOnly||{}),['${PDEPT}']:['STF_ATT']};`);
  await as(page, 'Principal'); await go(page, 'STF_ATT'); const before = await page.evaluate((k) => JSON.stringify(JSON.parse(localStorage.getItem(k) || window.__seed).staffAttendance).length, KEY);
  await page.locator('main button', { hasText: /^A$/ }).first().click(); await page.waitForTimeout(200); const t = await toast(page); const after = await page.evaluate((k) => JSON.stringify(JSON.parse(localStorage.getItem(k) || window.__seed).staffAttendance).length, KEY);
  return { actual: `${t || 'no message'}; ${before === after ? 'nothing saved' : 'SAVED'}`, pass: /Read only/.test(t) && before === after }; });

// ---------------------------------------------------------------- Tier & add-on visibility in the browser
const starter = demoConfig(RC, { ...blankOptions(RC), tier: 'STARTER', addons: {} });
const starterDash = demoConfig(RC, { ...blankOptions(RC), tier: 'STARTER', addons: { DASHBOARD: true, DESKS: true } });
const ADDON_SCREENS = [['DASH', 'Dashboard'], ['STU_REQUESTS', 'Coordinator Desk'], ['STU_GATE', 'Gate Desk'], ['STU_MEETINGS', 'Parent Meetings'], ['TRN_ROUTES', 'Routes, Stops & Timings'], ['OPS_CHANNELS', 'Web & App Screens'], ['OPS_TEMPLATES', 'Templates'], ['OPS_APPEARANCE', 'Appearance & Branding'], ['OPS_BACKUP', 'Backups & Restore']];
const addTenant = (id, cfg, tier) => `d.tenants=d.tenants.filter(t=>t.id!=='${id}'); d.tenants.push({id:'${id}',code:'QA${id.slice(-1)}',name:'QA ${tier} school (demo)',subdomain:'qa',plan:'${cfg.plan}',status:'Demo',overrides:${JSON.stringify(cfg.overrides)},examBoard:'CBSE',mobile:{enabled:true},renews:'—',demo:{tier:'${tier}',client:'QA'}}); d.tenantId='${id}';`;
for (const [tid, cfg, tierLabel, want] of [['TQ1', starter, 'Starter', []], ['TQ2', starterDash, 'Starter + Dashboard + Desks', ['DASH', 'STU_REQUESTS', 'STU_GATE', 'STU_MEETINGS']]]) {
  for (const role of ['Admin', 'Teacher', 'Front Office']) {
    await tc({ id: `UI-TIER-${tid}-${role.replace(/\W+/g, '')}`, module: 'Add-on menus', menu: ADDON_SCREENS.map((x) => x[1]).join(', '), feature: 'Add-on visibility', tier: tierLabel, addon: want.length ? 'DASHBOARD, DESKS' : 'none', role, type: want.length ? 'Positive' : 'Negative', category: 'UI visibility by add-on',
      title: `${tierLabel} demo school, ${role}: add-on menus ${want.length ? 'bought are shown, others hidden' : 'all hidden'}`, steps: `Open a ${tierLabel} demo school; sign in as ${role}; look at Main menu; open each add-on link directly`, expected: want.length ? 'Only Dashboard and the desks appear (where the role has them)' : 'None of: ' + ADDON_SCREENS.map((x) => x[1]).join(', ') },
    async (page) => { await as(page, 'Admin'); await inject(page, addTenant(tid, cfg, tierLabel)); await as(page, role); const m = await mainMenu(page); const all = Object.values(m).flat();
      const shown = ADDON_SCREENS.filter(([, l]) => all.includes(l)).map((x) => x[0]); const bad = shown.filter((c) => !want.includes(c));
      const direct = []; for (const [c] of ADDON_SCREENS.filter(([c]) => !want.includes(c)).slice(0, 4)) { await go(page, c); if ((await page.evaluate(() => location.hash)).includes(c)) direct.push(c); }
      return { actual: `Shown: ${shown.join(', ') || 'none'}${direct.length ? '; direct link opened: ' + direct.join(', ') : ''}`, pass: !bad.length && !direct.length }; });
  }
}
await tc({ id: 'UI-TIER-T2-Admin', module: 'Add-on menus', menu: ADDON_SCREENS.map((x) => x[1]).join(', '), feature: 'Add-on visibility', tier: 'Starter (app plan, existing school)', addon: 'none bought', role: 'Admin', type: 'Negative', category: 'UI visibility by tier',
  title: 'Sunrise Public School (Starter app plan, no add-ons): add-on menus hidden', steps: 'Switch to Sunrise; Admin; Main menu', expected: 'No Dashboard, desks, routes, Web & App Screens, Templates, Appearance, Backups' },
async (page) => { await as(page, 'Admin'); await inject(page, "d.tenantId='T2';"); await as(page, 'Admin'); const all = Object.values(await mainMenu(page)).flat(); const shown = ADDON_SCREENS.filter(([, l]) => all.includes(l)).map((x) => x[1]); return { actual: shown.length ? 'Shown: ' + shown.join(', ') : 'All hidden', pass: !shown.length }; });
await tc({ id: 'UI-TIER-Timings', module: 'Transport', menu: 'Routes, Stops & Timings', feature: 'Timings', tier: 'Pro+ / Transport add-on', addon: 'TIMINGS', role: 'Transport team', type: 'Negative', category: 'UI visibility by add-on',
  title: 'Without the Timings add-on, “Edit timings” is not offered', steps: 'Switch Timings off for the school; Transport team; Routes', expected: 'No “Edit timings” button' },
async (page) => { await as(page, 'Admin'); await inject(page, "const t=d.tenants.find(x=>x.id===d.tenantId); t.overrides={...(t.overrides||{}),FN_STOP_TIMINGS:false};"); await as(page, 'Transport team'); await go(page, 'TRN_ROUTES'); const n = await page.getByRole('button', { name: /Edit timings/ }).count(); return { actual: n ? '“Edit timings” shown' : 'Not shown', pass: !n }; });

// ---------------------------------------------------------------- Forms: required fields, formats, boundaries, duplicates, save and retrieve
const fill = async (scope, label, v, exact = true) => { const f = scope.getByLabel(label, { exact }); await f.first().fill(String(v)); };
const sel = async (scope, label, v) => { const f = scope.locator('label', { hasText: label }).locator('select').first(); const opts = await f.locator('option').evaluateAll((o) => o.map((x) => [x.value, x.textContent])); const hit = opts.find(([val, t]) => val === String(v) || t === String(v)) || opts[1] || opts[0]; await f.selectOption(hit[0]); };
const btn = (scope, name) => scope.getByRole('button', { name, exact: true }).first();

// New admission
const admit = async (page, o = {}) => { await as(page, 'Front Office'); await go(page, 'STU_ADMIT'); const m = page.locator('main');
  const v = { first: 'Kiran', dob: '2019-06-01', guardian: 'Suresh Rao', mobile: '9845012399', email: '', ...o };
  await fill(m, 'First name', v.first); await fill(m, 'Date of birth', v.dob); await fill(m, 'Guardian name', v.guardian); await fill(m, 'Mobile', v.mobile); if (v.email) await fill(m, 'Email (used for fee emails)', v.email); if (v.last) await fill(m, 'Last name', v.last);
  const b = btn(m, 'Save admission'); const dis = await b.isDisabled(); const err = await m.locator('.row.end .muted').innerText().catch(() => ''); return { m, b, dis, err }; };
const F = (meta, fn) => tc({ role: 'Front Office', module: 'Students', menu: 'New Admission', feature: 'New admission', ...meta }, fn);
await F({ id: 'UI-STU_ADMIT-01', type: 'Positive', category: 'Add/Save/Retrieve', title: 'Save a valid admission; it is listed after reload', steps: 'Fill first name, DOB, guardian, mobile 9845012399 → Save; reload; search All Students', expected: 'Admission number like 0042Q2026 shown; student found after reload' },
  async (page) => { const { b, dis } = await admit(page, { first: 'Qaadmit' }); if (dis) return { actual: 'Save disabled', pass: false }; await b.click(); const note = await page.locator('main .note').first().innerText(); await page.reload(); await page.waitForTimeout(300);
    const found = await page.evaluate((k) => JSON.parse(localStorage.getItem(k) || window.__seed).students.some((s) => s.first === 'Qaadmit'), KEY); return { actual: note.slice(0, 80) + ` · after reload: ${found ? 'found' : 'missing'}`, pass: /\d{4}[A-Z]2026/.test(note) && found }; });
await F({ id: 'UI-STU_ADMIT-02', type: 'Negative', category: 'Mandatory field', title: 'Empty form cannot be saved', steps: 'Open New Admission; touch nothing', expected: 'Save disabled with “First name is required”' },
  async (page) => { await as(page, 'Front Office'); await go(page, 'STU_ADMIT'); const m = page.locator('main'); const dis = await btn(m, 'Save admission').isDisabled(); const err = await m.locator('.row.end .muted').innerText(); return { actual: `${dis ? 'disabled' : 'enabled'}: ${err}`, pass: dis && /required/.test(err) }; });
for (const [k, mob, why] of [['03', '1234567890', 'starts with 1'], ['04', '98450', 'too short'], ['05', 'abcdefghij', 'letters']]) await F({ id: 'UI-STU_ADMIT-' + k, type: 'Negative', category: 'Wrong format', title: `Guardian mobile ${mob} (${why})`, steps: `Mobile ${mob}`, expected: 'Save disabled: must be 10 digits starting 6–9' },
  async (page) => { const { dis, err } = await admit(page, { mobile: mob }); return { actual: `${dis ? 'disabled' : 'enabled'}: ${err}`, pass: dis && /10 digits/.test(err) }; });
await F({ id: 'UI-STU_ADMIT-06', type: 'Negative', category: 'Wrong format', title: 'Email "ravi@school"', steps: 'Email without domain ending', expected: 'Email looks wrong' }, async (page) => { const { dis, err } = await admit(page, { email: 'ravi@school' }); return { actual: `${dis ? 'disabled' : 'enabled'}: ${err}`, pass: dis }; });
await F({ id: 'UI-STU_ADMIT-07', type: 'Negative', category: 'Invalid input', title: 'First name of spaces only', steps: 'First name "   "', expected: 'First name is required (spaces trimmed)' }, async (page) => { const { dis, err } = await admit(page, { first: '   ' }); return { actual: `${dis ? 'disabled' : 'enabled'}${err ? ': ' + err : ''}`, pass: dis }; });
await F({ id: 'UI-STU_ADMIT-08', type: 'Negative', category: 'Special characters', title: 'Name with digits and symbols "K1r@n#"', steps: 'First name K1r@n#', expected: 'Refused: letters, spaces, . \' - only' }, async (page) => { const { dis, err } = await admit(page, { first: 'K1r@n#' }); return { actual: `${dis ? 'disabled' : 'enabled'}${err ? ': ' + err : ''}`, pass: dis }; });
await F({ id: 'UI-STU_ADMIT-09', type: 'Negative', category: 'Boundary', title: 'Date of birth in the future', steps: 'DOB today+30', expected: 'Refused' }, async (page) => { const { dis, err } = await admit(page, { dob: plusDays(30) }); return { actual: `${dis ? 'disabled' : 'enabled'}${err ? ': ' + err : ''}`, pass: dis }; });
await F({ id: 'UI-STU_ADMIT-10', type: 'Negative', category: 'Boundary', title: 'Child aged 45 (DOB 1981)', steps: 'DOB 1981-01-01, Grade I', expected: 'Refused: age must fit the class' }, async (page) => { const { dis, err } = await admit(page, { dob: '1981-01-01' }); return { actual: `${dis ? 'disabled' : 'enabled'}${err ? ': ' + err : ''}`, pass: dis }; });
await F({ id: 'UI-STU_ADMIT-11', type: 'Negative', category: 'Wrong format', title: 'Mobile typed as "+91 98450 12399"', steps: 'Paste +91 98450 12399 → Save', expected: 'Corrected value shown before saving (“Will be saved as 9845012399”); saved as 9845012399' }, async (page) => { const { m, b, dis } = await admit(page, { mobile: '+91 98450 12399', first: 'Mobtest' }); const hint = await m.locator('#adm-mob').innerText().catch(() => ''); if (!dis) await b.click(); await page.waitForTimeout(200); const saved = await page.evaluate((k) => { const d = JSON.parse(localStorage.getItem(k) || window.__seed); const s = d.students.find((x) => x.first === 'Mobtest'); return s && d.guardians.find((g) => g.id === s.guardianId).mobile; }, KEY); return { actual: `hint “${hint}”; saved ${saved}`, pass: /9845012399/.test(hint) && saved === '9845012399' }; });
await F({ id: 'UI-STU_ADMIT-12', type: 'Negative', category: 'Duplicate', title: 'Same child admitted twice', steps: 'Save the same admission twice', expected: 'Second save warns about a possible duplicate' }, async (page) => { let r = await admit(page, { first: 'Twin', last: 'Same' }); await r.b.click(); await page.waitForTimeout(200); r = await admit(page, { first: 'Twin', last: 'Same' }); if (r.dis) return { actual: 'Blocked: ' + r.err, pass: true }; await r.b.click(); await page.waitForTimeout(200); const n = await page.evaluate((k) => JSON.parse(localStorage.getItem(k) || window.__seed).students.filter((s) => s.first === 'Twin').length, KEY); return { actual: `${n} records saved, no warning`, pass: n < 2 }; });

// Add staff / edit
