await S({ id: 'UI-STF_LIST-03', type: 'Negative', category: 'Duplicate', title: 'Short code already used on the timetable', steps: 'Short code of an existing teacher', expected: 'Refused: short code in use' }, async (page) => { await as(page, 'Admin'); const sh = await page.evaluate((k) => JSON.parse(localStorage.getItem(k) || window.__seed).staff.find((s) => s.short).short, KEY); const { dis, err } = await staffForm(page, { short: sh }); return { actual: `${sh}: ${dis ? 'disabled' : 'enabled'}${err ? ': ' + err : ''}`, pass: dis }; });
await S({ id: 'UI-STF_LIST-04', type: 'Negative', category: 'Boundary', title: 'Basic pay 0 and −1', steps: '0 then −1', expected: 'Basic pay must be more than 0' }, async (page) => { const r1 = await staffForm(page, { basic: 0 }); await fill(r1.m, 'Basic pay / month', -1); const r2 = { dis: await r1.b.isDisabled() }; return { actual: `0: ${r1.dis ? 'disabled' : 'enabled'}; −1: ${r2.dis ? 'disabled' : 'enabled'}`, pass: r1.dis && r2.dis }; });
await S({ id: 'UI-STF_LIST-05', type: 'Negative', category: 'Boundary', title: 'Basic pay ₹99,99,99,999 a month', steps: 'Basic 9999999999', expected: 'Refused or confirmed (unrealistic pay)' }, async (page) => { const r = await staffForm(page, { basic: 9999999999 }); return { actual: r.dis ? 'disabled: ' + r.err : 'enabled, would save', pass: r.dis }; });
await S({ id: 'UI-STF_LIST-06', type: 'Negative', category: 'Boundary', title: 'Date of joining far in the future (2099)', steps: 'Join 2099-01-01', expected: 'Refused' }, async (page) => { const r = await staffForm(page, { join: '2099-01-01' }); return { actual: r.dis ? 'disabled: ' + r.err : 'enabled, would save', pass: r.dis }; });
await S({ id: 'UI-STF_LIST-07', type: 'Negative', category: 'Wrong format', title: 'Email "teacher@@example.com"', steps: 'Bad email', expected: 'Email looks wrong' }, async (page) => { const r = await staffForm(page, { email: 'teacher@@example.com' }); return { actual: `${r.dis ? 'disabled' : 'enabled'}: ${r.err}`, pass: r.dis }; });
await S({ id: 'UI-STF_LIST-08', type: 'Positive', category: 'Edit', title: 'Edit a staff member\'s department and save; change is kept', steps: 'All Staff → Edit first row → change Short code → Save; reload', expected: 'Saved; new value after reload' }, async (page) => { await as(page, 'Admin'); await go(page, 'STF_LIST'); await page.locator('main button', { hasText: 'Edit' }).first().click(); const m = modal(page); await fill(m, 'Short code (timetable)', 'ZZQ'); await btn(m, 'Save').click(); await page.reload(); const ok = await page.evaluate((k) => JSON.parse(localStorage.getItem(k) || window.__seed).staff.some((s) => s.short === 'ZZQ'), KEY); return { actual: ok ? 'Saved and kept' : 'Not kept', pass: ok }; });
